# DataQ APP infra — Terraform / provider pins.
#
# This stack provisions the *application's own* production resources (ACA api +
# worker + frontend + migrate job + Postgres + Key Vault + App Insights + a
# self-hosted Redis broker) into the
# EXISTING dataq-rg. It is deliberately SEPARATE from the harness stack
# (~/Coding/Python/DataQ-harness/terraform — ADR 0021), which stands up the
# datasources + demo env. Only the subscription + resource group are shared.
#
# Local state backend — state is gitignored, never committed (it contains the
# generated Postgres password + secret values). Pin providers; do not float.

terraform {
  required_version = ">= 1.9"

  backend "local" {
    path = "terraform.tfstate"
  }

  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 4.0"
    }
    azuread = {
      source  = "hashicorp/azuread"
      version = "~> 3.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.12"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}
=== providers.tf ===
# Provider config. No credentials live here — auth comes from the ambient `az
# login` session (Owner on the subscription) or ARM_*/AZURE_* env vars. This
# stack applies as the Owner user (not the harness's Contributor-only SP), so it
# CAN register resource providers (rp.tf) and create role assignments
# (identity.tf / github_oidc.tf).

provider "azurerm" {
  features {
    key_vault {
      # Purge soft-deleted vaults on destroy so a re-apply can reuse the name.
      purge_soft_delete_on_destroy = true
    }
  }
  # We register the 4 missing RPs explicitly in rp.tf; don't let the provider
  # mass-register every RP on the subscription.
  resource_provider_registrations = "none"
}

provider "azuread" {
  # Tenant comes from the az login session (Default Directory). Creating the
  # GitHub-deploy app registration needs app-registration rights — fine as the
  # directory owner.
}

provider "random" {}
provider "time" {}
provider "null" {}

