    min_replicas = 1
    max_replicas = 1
    container {
      name    = "worker"
      image   = local.backend_image
      cpu     = 1.0
      memory  = "2Gi"
      command = ["celery", "-A", "backend.app.worker.celery_app", "worker", "-B", "--loglevel=INFO"]
      dynamic "env" {
        for_each = local.app_env
        content {
          name        = env.value.name
          value       = lookup(env.value, "value", null)
          secret_name = lookup(env.value, "secret_name", null)
        }
      }
    }
  }

  # Image is workflow-managed (see the api resource) — ignore it so an apply never
  # rolls the worker back to var.image_tag.
  lifecycle {
    ignore_changes = [template[0].container[0].image]
  }

  tags       = local.common_tags
  depends_on = [azurerm_role_assignment.kv_app_secrets]
}

